-- Combined Arizona course seed updater.
-- Generated from data/*course-seed.csv and data/*course-tee-seed.csv.
-- Safe to rerun: merges duplicate saved_courses, enforces upsert keys, then upserts courses, holes, and tees.

begin;

create extension if not exists pgcrypto;

create table if not exists public.saved_courses (
  id uuid primary key default gen_random_uuid(),
  source_provider text,
  source_course_id text,
  name text not null,
  normalized_name text not null,
  city text,
  state text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.saved_course_holes (
  id uuid primary key default gen_random_uuid(),
  saved_course_id uuid not null references public.saved_courses(id) on delete cascade,
  hole_number integer not null check (hole_number between 1 and 18),
  par integer check (par between 3 and 5),
  handicap_index integer check (handicap_index between 1 and 18),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.saved_course_tees (
  id uuid primary key default gen_random_uuid(),
  course_key text not null,
  course_name text not null,
  tee_name text not null,
  tee_color text not null,
  gender text,
  course_rating numeric not null,
  slope_rating numeric not null,
  total_yards integer,
  source_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.saved_course_tees add column if not exists tee_name text;
update public.saved_course_tees set tee_name = tee_color where tee_name is null;
alter table public.saved_course_tees alter column tee_name set not null;
alter table public.saved_course_tees add column if not exists gender text;
update public.saved_course_tees set gender = 'M' where gender is null;
alter table public.saved_course_tees add column if not exists total_yards integer;
alter table public.saved_course_tees add column if not exists source_url text;
alter table public.saved_course_tees drop constraint if exists saved_course_tees_course_key_tee_color_key;
drop index if exists public.saved_course_tees_course_key_tee_color_idx;

-- Deduplicate child tables before adding conflict targets used below.
with ranked_holes as (
  select
    id,
    row_number() over (
      partition by saved_course_id, hole_number
      order by updated_at desc nulls last, created_at asc nulls last, id
    ) as rn
  from public.saved_course_holes
)
delete from public.saved_course_holes h
using ranked_holes r
where h.id = r.id
  and r.rn > 1;

with ranked_tees as (
  select
    id,
    row_number() over (
      partition by course_key, tee_name, gender
      order by updated_at desc nulls last, total_yards desc nulls last, created_at asc nulls last, id
    ) as rn
  from public.saved_course_tees
)
delete from public.saved_course_tees t
using ranked_tees r
where t.id = r.id
  and r.rn > 1;

do $$ begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'saved_course_holes_saved_course_id_hole_number_key'
      and conrelid = 'public.saved_course_holes'::regclass
  ) then
    alter table public.saved_course_holes
      add constraint saved_course_holes_saved_course_id_hole_number_key unique (saved_course_id, hole_number);
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'saved_course_tees_course_key_tee_name_gender_key'
      and conrelid = 'public.saved_course_tees'::regclass
  ) then
    alter table public.saved_course_tees
      add constraint saved_course_tees_course_key_tee_name_gender_key unique (course_key, tee_name, gender);
  end if;
end $$;

-- Merge any existing duplicate course rows before enforcing/upserting by course identity.
with ranked_courses as (
  select
    id,
    first_value(id) over (
      partition by normalized_name, city, state
      order by case when source_provider = 'manual_seed' then 0 else 1 end, updated_at desc nulls last, created_at asc nulls last, id
    ) as keep_id,
    row_number() over (
      partition by normalized_name, city, state
      order by case when source_provider = 'manual_seed' then 0 else 1 end, updated_at desc nulls last, created_at asc nulls last, id
    ) as rn
  from public.saved_courses
  where normalized_name is not null
    and city is not null
    and state is not null
), duplicate_courses as (
  select id as duplicate_id, keep_id
  from ranked_courses
  where rn > 1
), copied_holes as (
  insert into public.saved_course_holes (saved_course_id, hole_number, par, handicap_index, created_at, updated_at)
  select d.keep_id, h.hole_number, h.par, h.handicap_index, coalesce(h.created_at, now()), now()
  from public.saved_course_holes h
  join duplicate_courses d on d.duplicate_id = h.saved_course_id
  on conflict (saved_course_id, hole_number) do update
    set par = coalesce(excluded.par, public.saved_course_holes.par),
        handicap_index = coalesce(excluded.handicap_index, public.saved_course_holes.handicap_index),
        updated_at = now()
  returning 1
), deleted_duplicate_holes as (
  delete from public.saved_course_holes h
  using duplicate_courses d
  where h.saved_course_id = d.duplicate_id
  returning 1
)
delete from public.saved_courses c
using duplicate_courses d
where c.id = d.duplicate_id;

do $$ begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'saved_courses_normalized_name_city_state_key'
      and conrelid = 'public.saved_courses'::regclass
  ) then
    alter table public.saved_courses
      add constraint saved_courses_normalized_name_city_state_key unique (normalized_name, city, state);
  end if;

end $$;

