  ('mount-graham-golf-club', 'Mount Graham Golf Club', 'Obsidian', 'Obsidian', 'M', 69.7, 116, 6573, 'https://18birdies.com/golf-courses/club/8e25b410-86ac-11e4-8c28-020000005b00/mt-graham-municipal-golf'),
  ('ironwood-country-club', 'Ironwood Country Club', 'Championship', 'Black', 'M', 64, 99, 5442, 'https://www.golfify.io/courses/ironwood-country-club'),
  ('ironwood-country-club', 'Ironwood Country Club', 'Blue', 'Blue', 'M', 64, 99, 5286, 'https://www.golfify.io/courses/ironwood-country-club'),
  ('ironwood-country-club', 'Ironwood Country Club', 'White', 'White', 'M', 61.5, 94, 4699, 'https://www.golfify.io/courses/ironwood-country-club')
), deduped_tee_seed as (
  select distinct on (course_key, tee_name, gender)
    course_key, course_name, tee_name, tee_color, gender, course_rating, slope_rating, total_yards, source_url
  from tee_seed
  order by course_key, tee_name, gender, total_yards desc nulls last
), upsert_courses as (
  insert into public.saved_courses (source_provider, source_course_id, name, normalized_name, city, state, updated_at)
  select 'manual_seed', course_key, course_name, course_key, city, state, now()
  from deduped_course_seed
  on conflict (normalized_name, city, state) do update
    set name = excluded.name,
        source_provider = excluded.source_provider,
        source_course_id = excluded.source_course_id,
        updated_at = now()
  returning id, normalized_name, city, state
), all_courses as (
  select c.id, s.*
  from deduped_course_seed s
  join public.saved_courses c
    on c.normalized_name = s.course_key
   and c.city is not distinct from s.city
   and c.state is not distinct from s.state
), upsert_tees as (
  insert into public.saved_course_tees (course_key, course_name, tee_name, tee_color, gender, course_rating, slope_rating, total_yards, source_url, updated_at)
  select course_key, course_name, tee_name, tee_color, gender, course_rating, slope_rating, total_yards, source_url, now()
  from deduped_tee_seed
  on conflict (course_key, tee_name, gender) do update
    set course_name = excluded.course_name,
        tee_color = excluded.tee_color,
        course_rating = excluded.course_rating,
        slope_rating = excluded.slope_rating,
        total_yards = excluded.total_yards,
        source_url = excluded.source_url,
        updated_at = now()
), upsert_holes as (
  insert into public.saved_course_holes (saved_course_id, hole_number, par, handicap_index, updated_at)
  select c.id, hole_number, c.pars[hole_number], c.hcps[hole_number], now()
  from all_courses c
  cross join generate_series(1,18) as hole_number
  on conflict (saved_course_id, hole_number) do update
    set par = excluded.par,
        handicap_index = excluded.handicap_index,
        updated_at = now()
  returning 1
)
select
  (select count(*) from deduped_course_seed) as seed_courses,
  (select count(*) from upsert_holes) as upserted_holes,
  (select count(*) from deduped_tee_seed) as seed_tee_rows;

select normalized_name, city, state, count(*) as duplicate_count
from public.saved_courses
where normalized_name is not null and city is not null and state is not null
group by normalized_name, city, state
having count(*) > 1
order by duplicate_count desc, normalized_name;

